INSERT INTO "site_page_content" ("page","draft_fields","draft_version","draft_updated_at","draft_updated_by","published_fields","published_version","published_updated_at","published_updated_by","previous_published_fields","previous_published_version","previous_published_updated_at","created_at") VALUES('ministries','{"page.title":"Ministries","page.intro":"Learn more about the ministries and leaders who serve the Mt. Moriah Missionary Baptist Church family.","profiles":[{"id":"ministries-1","name":"Music Department","title":"Elaine Fletcher, Pianist","bio":"The music department is responsible for music at morning service, midweek, the Lord’s Supper, Discipleship Training, and all evening and outside programs designated. The Music Department includes the Mass Choir, Women’s Choir, Youth Choir, and Male Chorus.","image":{"url":"https://mmmbc.com/wp-content/uploads/2025/05/Elaine.jpeg","alt":"Elaine Fletcher"}},{"id":"ministries-2","name":"Women’s Ministry","title":"Earlie Fugate, President","bio":"Our focus is to be a ministry where women are encouraged and enriched by studying and applying God’s Word.","image":{"url":"https://mmmbc.com/wp-content/uploads/2025/05/Earlie.jpeg","alt":"Earlie Fugate"}},{"id":"ministries-3","name":"Usher Board","title":"Richard Washington, President","bio":"The ushers shall attend to the seating of the congregation and to such other duties as may be directed.","image":{"url":"https://mmmbc.com/wp-content/uploads/2024/10/Richard-Washington.png","alt":"Richard Washington"}},{"id":"ministries-4","name":"Culinary Department","title":"Brenda Stokes, Department Head","bio":"It shall be the duty of this committee to organize feeding functions of the church.","image":{"url":"https://mmmbc.com/wp-content/uploads/2024/10/Brenda-Stokes.png","alt":"Brenda Stokes"}},{"id":"ministries-5","name":"First Aid Care Committee","title":"Tawanda Maxwell, President","bio":"Render services needed to the congregation.","image":{"url":"https://mmmbc.com/wp-content/uploads/2024/10/Image-Coming-Soon.png","alt":"First Aid Care Committee"}},{"id":"ministries-6","name":"Discipleship Training","title":"Minister Doralyn Warren & William Stanley Jones, Superintendents","bio":"Shall be responsible for training and teaching the membership how to become more like Christ.","image":{"url":"https://mmmbc.com/wp-content/uploads/2024/11/disciple-training.png","alt":"Discipleship Training"}},{"id":"ministries-7","name":"Transportation Committee","title":"Jesse Shields, Department Head","bio":"It shall be the responsibility of this committee to provide transportation for church services and activities. A schedule of drivers will be prepared, and drivers must possess a valid driver’s license.","image":{"url":"https://mmmbc.com/wp-content/uploads/2024/11/Jesse-Shields.jpg","alt":"Jesse Shields"}},{"id":"ministries-8","name":"Youth Department","title":"Tonya Gill, Department Head","bio":"To assist boys and girls, ages 5 and up, in the stages of transition to becoming healthy and strong Christian men and women.","image":{"url":"https://mmmbc.com/wp-content/uploads/2024/10/Tonya-Gill.png","alt":"Tonya Gill"}},{"id":"ministries-9","name":"Decorations","title":"Janice Jones, Department Head","bio":"It shall be the responsibility of this committee to decorate the sanctuary with seasonal decorations or decorations to present a particular theme. This committee is also responsible for decorations for special events.","image":{"url":"https://mmmbc.com/wp-content/uploads/2024/11/Janice-Jones.jpg","alt":"Janice Jones"}},{"id":"ministries-10","name":"Custodial","title":"Uvette Kizer & Margaret Faulkner","bio":"It shall be the responsibility of this committee to provide for the maintenance and upkeep of buildings.","image":{"url":"https://mmmbc.com/wp-content/uploads/2024/11/Custodial.png","alt":"Custodial Ministry"}},{"id":"ministries-11","name":"Lawn Keeper","title":"Derek Strong, Department Head","bio":"It shall be the responsibility of this committee to provide for the maintenance and upkeep of buildings and grounds. This shall consist of exterior and interior.","image":{"url":"https://mmmbc.com/wp-content/uploads/2024/10/Derek-Strong.png","alt":"Derek Strong"}},{"id":"ministries-12","name":"Courtesy / Hospitality","title":"Mary Dumas, Department Head","bio":"It shall be the duty of this committee to welcome visitors to church services, membership to church services, and visiting churches.","image":{"url":"https://mmmbc.com/wp-content/uploads/2024/11/Mary-Dumas.jpg","alt":"Mary Dumas"}},{"id":"ministries-13","name":"Photographer","title":"Elbert Speers","bio":"It shall be the duty of the committee to gather and maintain any and all pictures that will contribute to the cumulative history of the church.","image":{"url":"https://mmmbc.com/wp-content/uploads/2024/10/Elbert-Speers.png","alt":"Elbert Speers"}},{"id":"ministries-14","name":"Video / Audio Ministry","title":"Calvin Cole, Jr., Elbert Spears, Derek Strong","bio":"One who controls the sound/volume. Also, one who records the services for those who desire a copy or cannot attend service in person.","image":{"url":"https://mmmbc.com/wp-content/uploads/2024/11/Video.png","alt":"Video / Audio Ministry"}}]}',1,'2026-09-21T18:14:12.902Z','system:migration','{"page.title":"Ministries","page.intro":"Learn more about the ministries and leaders who serve the Mt. Moriah Missionary Baptist Church family.","profiles":[{"id":"ministries-1","name":"Music Department","title":"Elaine Fletcher, Pianist","bio":"The music department is responsible for music at morning service, midweek, the Lord’s Supper, Discipleship Training, and all evening and outside programs designated. The Music Department includes the Mass Choir, Women’s Choir, Youth Choir, and Male Chorus.","image":{"url":"https://mmmbc.com/wp-content/uploads/2025/05/Elaine.jpeg","alt":"Elaine Fletcher"}},{"id":"ministries-2","name":"Women’s Ministry","title":"Earlie Fugate, President","bio":"Our focus is to be a ministry where women are encouraged and enriched by studying and applying God’s Word.","image":{"url":"https://mmmbc.com/wp-content/uploads/2025/05/Earlie.jpeg","alt":"Earlie Fugate"}},{"id":"ministries-3","name":"Usher Board","title":"Richard Washington, President","bio":"The ushers shall attend to the seating of the congregation and to such other duties as may be directed.","image":{"url":"https://mmmbc.com/wp-content/uploads/2024/10/Richard-Washington.png","alt":"Richard Washington"}},{"id":"ministries-4","name":"Culinary Department","title":"Brenda Stokes, Department Head","bio":"It shall be the duty of this committee to organize feeding functions of the church.","image":{"url":"https://mmmbc.com/wp-content/uploads/2024/10/Brenda-Stokes.png","alt":"Brenda Stokes"}},{"id":"ministries-5","name":"First Aid Care Committee","title":"Tawanda Maxwell, President","bio":"Render services needed to the congregation.","image":{"url":"https://mmmbc.com/wp-content/uploads/2024/10/Image-Coming-Soon.png","alt":"First Aid Care Committee"}},{"id":"ministries-6","name":"Discipleship Training","title":"Minister Doralyn Warren & William Stanley Jones, Superintendents","bio":"Shall be responsible for training and teaching the membership how to become more like Christ.","image":{"url":"https://mmmbc.com/wp-content/uploads/2024/11/disciple-training.png","alt":"Discipleship Training"}},{"id":"ministries-7","name":"Transportation Committee","title":"Jesse Shields, Department Head","bio":"It shall be the responsibility of this committee to provide transportation for church services and activities. A schedule of drivers will be prepared, and drivers must possess a valid driver’s license.","image":{"url":"https://mmmbc.com/wp-content/uploads/2024/11/Jesse-Shields.jpg","alt":"Jesse Shields"}},{"id":"ministries-8","name":"Youth Department","title":"Tonya Gill, Department Head","bio":"To assist boys and girls, ages 5 and up, in the stages of transition to becoming healthy and strong Christian men and women.","image":{"url":"https://mmmbc.com/wp-content/uploads/2024/10/Tonya-Gill.png","alt":"Tonya Gill"}},{"id":"ministries-9","name":"Decorations","title":"Janice Jones, Department Head","bio":"It shall be the responsibility of this committee to decorate the sanctuary with seasonal decorations or decorations to present a particular theme. This committee is also responsible for decorations for special events.","image":{"url":"https://mmmbc.com/wp-content/uploads/2024/11/Janice-Jones.jpg","alt":"Janice Jones"}},{"id":"ministries-10","name":"Custodial","title":"Uvette Kizer & Margaret Faulkner","bio":"It shall be the responsibility of this committee to provide for the maintenance and upkeep of buildings.","image":{"url":"https://mmmbc.com/wp-content/uploads/2024/11/Custodial.png","alt":"Custodial Ministry"}},{"id":"ministries-11","name":"Lawn Keeper","title":"Derek Strong, Department Head","bio":"It shall be the responsibility of this committee to provide for the maintenance and upkeep of buildings and grounds. This shall consist of exterior and interior.","image":{"url":"https://mmmbc.com/wp-content/uploads/2024/10/Derek-Strong.png","alt":"Derek Strong"}},{"id":"ministries-12","name":"Courtesy / Hospitality","title":"Mary Dumas, Department Head","bio":"It shall be the duty of this committee to welcome visitors to church services, membership to church services, and visiting churches.","image":{"url":"https://mmmbc.com/wp-content/uploads/2024/11/Mary-Dumas.jpg","alt":"Mary Dumas"}},{"id":"ministries-13","name":"Photographer","title":"Elbert Speers","bio":"It shall be the duty of the committee to gather and maintain any and all pictures that will contribute to the cumulative history of the church.","image":{"url":"https://mmmbc.com/wp-content/uploads/2024/10/Elbert-Speers.png","alt":"Elbert Speers"}},{"id":"ministries-14","name":"Video / Audio Ministry","title":"Calvin Cole, Jr., Elbert Spears, Derek Strong","bio":"One who controls the sound/volume. Also, one who records the services for those who desire a copy or cannot attend service in person.","image":{"url":"https://mmmbc.com/wp-content/uploads/2024/11/Video.png","alt":"Video / Audio Ministry"}}]}',1,'2026-09-21T18:14:12.902Z','system:migration',NULL,NULL,NULL,'2026-09-21T18:14:12.902Z');
