INSERT INTO "site_page_content" ("page","draft_fields","draft_version","draft_updated_at","draft_updated_by","published_fields","published_version","published_updated_at","published_updated_by","previous_published_fields","previous_published_version","previous_published_updated_at","created_at") VALUES('leadership','{"page.title":"Leadership & Staff","sections.staff.heading":"Staff","sections.deacons.heading":"Deacons","sections.deacons.intro":"<p>The deacons are ordained to do their work according to Acts 6:1-8, 1 Timothy 3:8-13 and Titus 2.</p><p>The deacons assist the pastor, cooperate with the pastor in providing the pulpit supply and the leaders of the prayer meeting; visit members; care for the sick and needy and distressed members of the church. The board shall promote Christian instruction and ministry to the church membership.</p>","sections.deaconesses.heading":"Deaconesses","sections.official_team.heading":"Official Team & Trustees","profiles":[{"id":"leadership-1","group":"staff","name":"Rev. Stephen Harvey","title":"Pastor","bio":"Stephen Harvey, a native of Paducah, Kentucky, received his Bachelor of Social Work and minor in Physical Education from Murray State University and is pursuing a Master’s in Human Development and Leadership. He was licensed to preach in 2005, ordained in 2011, and has served as an associate minister, youth director, teacher, treasurer, and pastor. He is retired from the Mayfield Youth Development Center and continues to give God all the praise, honor, and glory for the opportunity to be His humble servant.","image":{"url":"/cdn/gallery/site/pastorHarvey.jpeg","alt":"Rev. Stephen Harvey"}},{"id":"leadership-2","group":"staff","name":"Marsha Roundtree","title":"Church Administrative Assistant","bio":"Keeps complete records of the transactions of all business meetings; keeps records of church membership and baptism; prepares bulletins and correspondence; sends annual giving statements to members; and serves as finance secretary in assisting the finance chairman.","image":{"url":"../ConImg/webPages/leadership_staff_image1.jpeg","alt":"Marsha Roundtree"}},{"id":"leadership-3","group":"staff","name":"Weldon Stokes","title":"Finance Chairman","bio":"The Finance Chairman is responsible for the financial records of the church. Weldon Stokes has served as a deacon for over 30 years and is a member of the Usher Ministry, Culinary Ministry, and Official Team.","image":{"url":"../ConImg/webPages/leadership_staff_image2.png","alt":"Weldon Stokes"}},{"id":"leadership-4","group":"staff","name":"John Burnett","title":"Finance Vice Chair","bio":"The Finance Vice Chairman supports the finance chairman and is responsible for financial records when the chairman is not available. John Burnett has served as a deacon for over 20 years and is active in the Ushers Ministry, Culinary Ministry, and Official Team.","image":{"url":"../ConImg/webPages/leadership_staff_image3.jpeg","alt":"John Burnett"}}]}',1,'2026-09-27T17:33:47.752Z','system:migration','{"page.title":"Leadership & Staff","sections.staff.heading":"Staff","sections.deacons.heading":"Deacons","sections.deacons.intro":"<p>The deacons are ordained to do their work according to Acts 6:1-8, 1 Timothy 3:8-13 and Titus 2.</p><p>The deacons assist the pastor, cooperate with the pastor in providing the pulpit supply and the leaders of the prayer meeting; visit members; care for the sick and needy and distressed members of the church. The board shall promote Christian instruction and ministry to the church membership.</p>","sections.deaconesses.heading":"Deaconesses","sections.official_team.heading":"Official Team & Trustees","profiles":[{"id":"leadership-1","group":"staff","name":"Rev. Stephen Harvey","title":"Pastor","bio":"Stephen Harvey, a native of Paducah, Kentucky, received his Bachelor of Social Work and minor in Physical Education from Murray State University and is pursuing a Master’s in Human Development and Leadership. He was licensed to preach in 2005, ordained in 2011, and has served as an associate minister, youth director, teacher, treasurer, and pastor. He is retired from the Mayfield Youth Development Center and continues to give God all the praise, honor, and glory for the opportunity to be His humble servant.","image":{"url":"/cdn/gallery/site/pastorHarvey.jpeg","alt":"Rev. Stephen Harvey"}},{"id":"leadership-2","group":"staff","name":"Marsha Roundtree","title":"Church Administrative Assistant","bio":"Keeps complete records of the transactions of all business meetings; keeps records of church membership and baptism; prepares bulletins and correspondence; sends annual giving statements to members; and serves as finance secretary in assisting the finance chairman.","image":{"url":"../ConImg/webPages/leadership_staff_image1.jpeg","alt":"Marsha Roundtree"}},{"id":"leadership-3","group":"staff","name":"Weldon Stokes","title":"Finance Chairman","bio":"The Finance Chairman is responsible for the financial records of the church. Weldon Stokes has served as a deacon for over 30 years and is a member of the Usher Ministry, Culinary Ministry, and Official Team.","image":{"url":"../ConImg/webPages/leadership_staff_image2.png","alt":"Weldon Stokes"}},{"id":"leadership-4","group":"staff","name":"John Burnett","title":"Finance Vice Chair","bio":"The Finance Vice Chairman supports the finance chairman and is responsible for financial records when the chairman is not available. John Burnett has served as a deacon for over 20 years and is active in the Ushers Ministry, Culinary Ministry, and Official Team.","image":{"url":"../ConImg/webPages/leadership_staff_image3.jpeg","alt":"John Burnett"}}]}',1,'2026-09-27T17:33:47.752Z','system:migration',NULL,NULL,NULL,'2026-09-27T17:33:47.752Z');
INSERT INTO "site_page_content" ("page","draft_fields","draft_version","draft_updated_at","draft_updated_by","published_fields","published_version","published_updated_at","published_updated_by","previous_published_fields","previous_published_version","previous_published_updated_at","created_at") VALUES('deacons','{"page.title":"Deacons","profiles":[{"id":"deacons-1","name":"John Burnett","title":"Chairman of Deacons","bio":"Deacon Burnett has served for over 20 years, serves as vice-president of the Ushers Ministry, Finance Vice-Chairman, and is a member of Culinary Ministry and the Official Team.","image":{"url":"../ConImg/webPages/deacons_image1.jpeg","alt":"John Burnett"}},{"id":"deacons-2","name":"Thomas L. Biles","title":"","bio":"Deacon for over 40 years, member of the Male Chorus, Discipleship Training teacher, and member of the Official Team.","image":{"url":"../ConImg/webPages/deacons_image2.jpeg","alt":"Thomas L. Biles"}},{"id":"deacons-3","name":"Mario Johnson","title":"","bio":"Deacon for more than 15 years and member of the Official Team.","image":{"url":"../ConImg/webPages/deacons_image3.jpeg","alt":"Mario Johnson"}},{"id":"deacons-4","name":"William S. Jones","title":"","bio":"Deacon for over 30 years, Vice-chairman Trustee Board, and member of the Usher Ministry, Male Chorus, Official Team, and Discipleship Training team.","image":{"url":"../ConImg/webPages/deacons_image4.jpeg","alt":"William S. Jones"}},{"id":"deacons-5","name":"Weldon Stokes","title":"","bio":"Deacon for over 30 years, Finance Chief, member of the Usher Ministry and Culinary Ministry, and Official Team Secretary.","image":{"url":"../ConImg/webPages/deacons_image5.png","alt":"Weldon Stokes"}},{"id":"deacons-6","name":"David Jones, Sr.","title":"","bio":"Ordained as a deacon on June 21, 2013. Member of the Male Chorus and Official Team.","image":{"url":"../ConImg/webPages/deacons_image6.jpeg","alt":"David Jones, Sr."}}]}',1,'2026-09-27T17:33:47.757Z','system:migration','{"page.title":"Deacons","profiles":[{"id":"deacons-1","name":"John Burnett","title":"Chairman of Deacons","bio":"Deacon Burnett has served for over 20 years, serves as vice-president of the Ushers Ministry, Finance Vice-Chairman, and is a member of Culinary Ministry and the Official Team.","image":{"url":"../ConImg/webPages/deacons_image1.jpeg","alt":"John Burnett"}},{"id":"deacons-2","name":"Thomas L. Biles","title":"","bio":"Deacon for over 40 years, member of the Male Chorus, Discipleship Training teacher, and member of the Official Team.","image":{"url":"../ConImg/webPages/deacons_image2.jpeg","alt":"Thomas L. Biles"}},{"id":"deacons-3","name":"Mario Johnson","title":"","bio":"Deacon for more than 15 years and member of the Official Team.","image":{"url":"../ConImg/webPages/deacons_image3.jpeg","alt":"Mario Johnson"}},{"id":"deacons-4","name":"William S. Jones","title":"","bio":"Deacon for over 30 years, Vice-chairman Trustee Board, and member of the Usher Ministry, Male Chorus, Official Team, and Discipleship Training team.","image":{"url":"../ConImg/webPages/deacons_image4.jpeg","alt":"William S. Jones"}},{"id":"deacons-5","name":"Weldon Stokes","title":"","bio":"Deacon for over 30 years, Finance Chief, member of the Usher Ministry and Culinary Ministry, and Official Team Secretary.","image":{"url":"../ConImg/webPages/deacons_image5.png","alt":"Weldon Stokes"}},{"id":"deacons-6","name":"David Jones, Sr.","title":"","bio":"Ordained as a deacon on June 21, 2013. Member of the Male Chorus and Official Team.","image":{"url":"../ConImg/webPages/deacons_image6.jpeg","alt":"David Jones, Sr."}}]}',1,'2026-09-27T17:33:47.757Z','system:migration',NULL,NULL,NULL,'2026-09-27T17:33:47.757Z');
INSERT INTO "site_page_content" ("page","draft_fields","draft_version","draft_updated_at","draft_updated_by","published_fields","published_version","published_updated_at","published_updated_by","previous_published_fields","previous_published_version","previous_published_updated_at","created_at") VALUES('associate_ministers','{"page.title":"Associate Ministers","profiles":[{"id":"associate-ministers-1","name":"Evangelist Melanie Nunn","title":"","bio":"Before moving to Paducah, she and her family lived in Detroit, MI for twenty-five years where she taught English and Journalism at Henry Ford High School. Evangelist Nunn responded to God’s call in 2000 and has never looked back. She is an associate minister at Mount Moriah Missionary Baptist Church in Paducah, KY where she also served as Superintendent of Disciples in Training. She considers it an honor to be both licensed and ordained by her father in the ministry and pastor, Reverend Dr. Calvin Cole, Sr.","image":{"url":"../ConImg/webPages/ministries_image1.png","alt":"Evangelist Melanie Nunn"}},{"id":"associate-ministers-2","name":"Elder Jimmy Jones","title":"","bio":"Elder Jones was born in Cairo IL, graduated from Sumner High School and West KY Vocational-Technical School, and attended Coyne Electronic Institute for 15 months. He was an employee of USEC for 37 years in instrument maintenance. He was married to Teressia Jones for 38 years and from this union they have four children. Elder Jones was ordained February 18, 1996, at Higher Dimensions Church, Paducah, KY by Rev. Zachery Strong.","image":{"url":"../ConImg/webPages/ministries_image2.jpeg","alt":"Elder Jimmy Jones"}},{"id":"associate-ministers-3","name":"Rev. Fairly Taylor","title":"","bio":"Reverend Fairley Taylor Jr. is the son of Brenda Taylor and the late Fairley Taylor Sr. He grew up in Hopkinsville, KY, received his commission in 1988 as a U.S. Army officer, and graduated from Murray State University in 1989 with a Bachelor of Science degree in Animal Science. He was ordained as a deacon in 1991, called into ministry in 2005, and received his license to preach January 4, 2007 from Reverend Dr. W.G. Harvey Sr. at New Greater Love Missionary Baptist Church in Paducah, KY.","image":{"url":"../ConImg/webPages/ministries_image3.png","alt":"Rev. Fairly Taylor"}},{"id":"associate-ministers-4","name":"Minister Joyce Shields","title":"","bio":"Joyce Marie Harden-Shields is the second oldest of five children born to Leon (deceased) and Joyce Harden. She accepted Jesus Christ as her Lord and Savior at fourteen, moved to Paducah in 1996, joined White Oak Missionary Baptist Church in 1997, and moved her membership to Mt. Moriah in 2001. She accepted the call into ministry on March 31, 2019 and has served as president of the Missionary Circle, Discipleship Training Superintendent, and Women’s Ministry secretary.","image":{"url":"../ConImg/webPages/ministries_image4.jpeg","alt":"Minister Joyce Shields"}},{"id":"associate-ministers-5","name":"Minister Doralyn Warren","title":"","bio":"Doralyn Warren is an instructor in the Nursing Assistant Program at West Kentucky Community and Technical College. She previously worked in long-term care for over 40 years and sees caring for the elderly as a calling. She earned a Bachelor of Science in Nursing from Wesleyan University in 2010 and is attending Newburgh Seminary for a Master of Ministry degree.","image":{"url":"../ConImg/webPages/ministries_image5.png","alt":"Minister Doralyn Warren"}},{"id":"associate-ministers-6","name":"Rev. Dennis Gray","title":"","bio":"Pastor Dennis Gray, a native of Hickman, Kentucky, is a commissioned minister of the Christian Church (Disciple of Christ). He served as pastor of Second Christian Church in Mayfield, KY for 23 years and now serves Mt. Moriah Missionary Baptist Church in Paducah, Kentucky as an Associate Minister. Pastor Gray is the husband of Sue Gray, and they have three children and four grandchildren.","image":{"url":"../ConImg/webPages/ministries_image6.jpeg","alt":"Rev. Dennis Gray"}}]}',1,'2026-09-27T17:33:47.754Z','system:migration','{"page.title":"Associate Ministers","profiles":[{"id":"associate-ministers-1","name":"Evangelist Melanie Nunn","title":"","bio":"Before moving to Paducah, she and her family lived in Detroit, MI for twenty-five years where she taught English and Journalism at Henry Ford High School. Evangelist Nunn responded to God’s call in 2000 and has never looked back. She is an associate minister at Mount Moriah Missionary Baptist Church in Paducah, KY where she also served as Superintendent of Disciples in Training. She considers it an honor to be both licensed and ordained by her father in the ministry and pastor, Reverend Dr. Calvin Cole, Sr.","image":{"url":"../ConImg/webPages/ministries_image1.png","alt":"Evangelist Melanie Nunn"}},{"id":"associate-ministers-2","name":"Elder Jimmy Jones","title":"","bio":"Elder Jones was born in Cairo IL, graduated from Sumner High School and West KY Vocational-Technical School, and attended Coyne Electronic Institute for 15 months. He was an employee of USEC for 37 years in instrument maintenance. He was married to Teressia Jones for 38 years and from this union they have four children. Elder Jones was ordained February 18, 1996, at Higher Dimensions Church, Paducah, KY by Rev. Zachery Strong.","image":{"url":"../ConImg/webPages/ministries_image2.jpeg","alt":"Elder Jimmy Jones"}},{"id":"associate-ministers-3","name":"Rev. Fairly Taylor","title":"","bio":"Reverend Fairley Taylor Jr. is the son of Brenda Taylor and the late Fairley Taylor Sr. He grew up in Hopkinsville, KY, received his commission in 1988 as a U.S. Army officer, and graduated from Murray State University in 1989 with a Bachelor of Science degree in Animal Science. He was ordained as a deacon in 1991, called into ministry in 2005, and received his license to preach January 4, 2007 from Reverend Dr. W.G. Harvey Sr. at New Greater Love Missionary Baptist Church in Paducah, KY.","image":{"url":"../ConImg/webPages/ministries_image3.png","alt":"Rev. Fairly Taylor"}},{"id":"associate-ministers-4","name":"Minister Joyce Shields","title":"","bio":"Joyce Marie Harden-Shields is the second oldest of five children born to Leon (deceased) and Joyce Harden. She accepted Jesus Christ as her Lord and Savior at fourteen, moved to Paducah in 1996, joined White Oak Missionary Baptist Church in 1997, and moved her membership to Mt. Moriah in 2001. She accepted the call into ministry on March 31, 2019 and has served as president of the Missionary Circle, Discipleship Training Superintendent, and Women’s Ministry secretary.","image":{"url":"../ConImg/webPages/ministries_image4.jpeg","alt":"Minister Joyce Shields"}},{"id":"associate-ministers-5","name":"Minister Doralyn Warren","title":"","bio":"Doralyn Warren is an instructor in the Nursing Assistant Program at West Kentucky Community and Technical College. She previously worked in long-term care for over 40 years and sees caring for the elderly as a calling. She earned a Bachelor of Science in Nursing from Wesleyan University in 2010 and is attending Newburgh Seminary for a Master of Ministry degree.","image":{"url":"../ConImg/webPages/ministries_image5.png","alt":"Minister Doralyn Warren"}},{"id":"associate-ministers-6","name":"Rev. Dennis Gray","title":"","bio":"Pastor Dennis Gray, a native of Hickman, Kentucky, is a commissioned minister of the Christian Church (Disciple of Christ). He served as pastor of Second Christian Church in Mayfield, KY for 23 years and now serves Mt. Moriah Missionary Baptist Church in Paducah, Kentucky as an Associate Minister. Pastor Gray is the husband of Sue Gray, and they have three children and four grandchildren.","image":{"url":"../ConImg/webPages/ministries_image6.jpeg","alt":"Rev. Dennis Gray"}}]}',1,'2026-09-27T17:33:47.754Z','system:migration',NULL,NULL,NULL,'2026-09-27T17:33:47.754Z');
