INSERT INTO "site_page_content" ("page","draft_fields","draft_version","draft_updated_at","draft_updated_by","published_fields","published_version","published_updated_at","published_updated_by","previous_published_fields","previous_published_version","previous_published_updated_at","created_at") VALUES('facility_rental','{"page.title":"Facility Rental","sections.rental.heading1":"Sacred Celebrations","sections.rental.description":"<p>Your wedding or other special event must be a sacred celebration. Your plans for the service should reflect that fact and also align with the beliefs and worship practices of Mt. Moriah Missionary Baptist Church. Careful planning will ensure that your wedding is meaningful to you, your family, and friends.</p><p>Mt. Moriah Missionary Baptist Church seats up to 250 people, and the fellowship and educational building seating is 200.</p>","sections.rental.heading2":"Submit a Request for Building Rental","contact.email":"mtmoriahmbc@comcast.net","contact.phone":"(270) 443-3714","availability":"open"}',1,'2026-10-05T02:41:43.873Z','system:migration','{"page.title":"Facility Rental","sections.rental.heading1":"Sacred Celebrations","sections.rental.description":"<p>Your wedding or other special event must be a sacred celebration. Your plans for the service should reflect that fact and also align with the beliefs and worship practices of Mt. Moriah Missionary Baptist Church. Careful planning will ensure that your wedding is meaningful to you, your family, and friends.</p><p>Mt. Moriah Missionary Baptist Church seats up to 250 people, and the fellowship and educational building seating is 200.</p>","sections.rental.heading2":"Submit a Request for Building Rental","contact.email":"mtmoriahmbc@comcast.net","contact.phone":"(270) 443-3714","availability":"open"}',1,'2026-10-05T02:41:43.873Z','system:migration',NULL,NULL,NULL,'2026-10-05T02:41:43.873Z');
