PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE gallery_items (
  id TEXT PRIMARY KEY,
  album TEXT NOT NULL,
  label TEXT NOT NULL,
  tags_json TEXT NOT NULL,
  file_key TEXT NOT NULL,
  thumb_key TEXT,
  original_name TEXT NOT NULL,
  created_at TEXT NOT NULL,
  position INTEGER
, is_hidden INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS "d1_migrations"(
		id         INTEGER PRIMARY KEY AUTOINCREMENT,
		name       TEXT UNIQUE,
		applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE events (
  id TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  event_date TEXT NOT NULL,
  event_time TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE TABLE announcements (
  id TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  body TEXT NOT NULL,
  created_at TEXT NOT NULL,
  expires_at TEXT
);
CREATE TABLE bulletins (
  id TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  file_key TEXT NOT NULL,
  original_name TEXT,
  starts_at TEXT,
  ends_at TEXT,
  created_at TEXT NOT NULL
);
CREATE TABLE subscribers (
  id TEXT PRIMARY KEY,
  email TEXT NOT NULL UNIQUE,
  name TEXT,
  status TEXT NOT NULL DEFAULT 'active',
  created_at TEXT NOT NULL
);
CREATE TABLE finance_entries (
  id TEXT PRIMARY KEY,
  entry_date TEXT NOT NULL,
  type TEXT NOT NULL,
  category TEXT,
  fund TEXT,
  method TEXT,
  party TEXT,
  memo TEXT,
  amount_cents INTEGER NOT NULL,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
, fund_id TEXT, status TEXT NOT NULL DEFAULT 'posted', voided_by TEXT, voided_at TEXT, void_reason TEXT);
CREATE TABLE profiles (
  id TEXT PRIMARY KEY,
  section TEXT NOT NULL,
  name TEXT NOT NULL,
  title TEXT,
  bio TEXT,
  image_key TEXT,
  position INTEGER,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE TABLE giving_donations (
  id TEXT PRIMARY KEY,
  stripe_event_id TEXT,
  stripe_checkout_session_id TEXT UNIQUE,
  stripe_payment_intent_id TEXT,
  stripe_subscription_id TEXT,
  stripe_connected_account_id TEXT,
  donor_name TEXT,
  donor_email TEXT,
  fund_code TEXT NOT NULL,
  frequency TEXT NOT NULL,
  amount_cents INTEGER NOT NULL,
  platform_fee_cents INTEGER NOT NULL DEFAULT 0,
  currency TEXT NOT NULL DEFAULT 'usd',
  payment_status TEXT NOT NULL,
  payment_method_type TEXT,
  note TEXT,
  created_at TEXT NOT NULL,
  paid_at TEXT,
  updated_at TEXT NOT NULL
);
CREATE TABLE stripe_webhook_events (
  stripe_event_id TEXT PRIMARY KEY,
  event_type TEXT NOT NULL,
  connected_account_id TEXT,
  processed_at TEXT NOT NULL
);
CREATE TABLE giving_subscription_payments (
  id TEXT PRIMARY KEY,
  stripe_event_id TEXT,
  stripe_invoice_id TEXT UNIQUE NOT NULL,
  stripe_subscription_id TEXT,
  stripe_payment_intent_id TEXT,
  stripe_connected_account_id TEXT,
  donor_name TEXT,
  donor_email TEXT,
  fund_code TEXT NOT NULL,
  amount_due_cents INTEGER NOT NULL DEFAULT 0,
  amount_paid_cents INTEGER NOT NULL DEFAULT 0,
  platform_fee_cents INTEGER NOT NULL DEFAULT 0,
  currency TEXT NOT NULL DEFAULT 'usd',
  payment_status TEXT NOT NULL,
  billing_reason TEXT,
  period_start TEXT,
  period_end TEXT,
  paid_at TEXT,
  failed_at TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE TABLE giving_subscriptions (
  stripe_subscription_id TEXT PRIMARY KEY,
  stripe_connected_account_id TEXT,
  stripe_customer_id TEXT,
  donor_name TEXT,
  donor_email TEXT,
  fund_code TEXT NOT NULL,
  amount_cents INTEGER NOT NULL DEFAULT 0,
  platform_fee_percent REAL NOT NULL DEFAULT 2.5,
  currency TEXT NOT NULL DEFAULT 'usd',
  status TEXT NOT NULL,
  cancel_at_period_end INTEGER NOT NULL DEFAULT 0,
  current_period_start TEXT,
  current_period_end TEXT,
  canceled_at TEXT,
  ended_at TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE TABLE admin_invites (
  id TEXT PRIMARY KEY,
  email TEXT NOT NULL UNIQUE,
  role TEXT NOT NULL DEFAULT 'website_editor',
  status TEXT NOT NULL DEFAULT 'invited', 
  invited_by TEXT,
  invited_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE TABLE newsletter_records (
  id TEXT PRIMARY KEY,
  subject TEXT NOT NULL,
  message TEXT NOT NULL,
  emails TEXT NOT NULL DEFAULT '[]', 
  status TEXT NOT NULL, 
  sent_count INTEGER NOT NULL DEFAULT 0,
  schedule_at TEXT,
  schedule_date TEXT,
  schedule_time TEXT,
  schedule_timezone TEXT,
  retry_count INTEGER NOT NULL DEFAULT 0,
  error TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  sent_at TEXT
);
CREATE TABLE site_page_content (
  page TEXT PRIMARY KEY,
  draft_fields TEXT NOT NULL DEFAULT '{}',
  draft_version INTEGER NOT NULL DEFAULT 0,
  draft_updated_at TEXT,
  draft_updated_by TEXT,
  published_fields TEXT NOT NULL DEFAULT '{}',
  published_version INTEGER NOT NULL DEFAULT 0,
  published_updated_at TEXT,
  published_updated_by TEXT,
  previous_published_fields TEXT,
  previous_published_version INTEGER,
  previous_published_updated_at TEXT,
  created_at TEXT NOT NULL
);
CREATE TABLE gallery_preferences (
      id INTEGER PRIMARY KEY,
      show_image_names INTEGER NOT NULL DEFAULT 1,
      updated_at TEXT NOT NULL
    );
CREATE TABLE finance_funds (
      id TEXT PRIMARY KEY,
      fund_name TEXT NOT NULL UNIQUE,
      fund_code TEXT,
      active INTEGER NOT NULL DEFAULT 1,
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL
    );
CREATE TABLE finance_meta (
      key TEXT PRIMARY KEY,
      value_json TEXT NOT NULL,
      updated_at TEXT NOT NULL
    );
CREATE TABLE finance_donors (
      id TEXT PRIMARY KEY,
      first_name TEXT NOT NULL,
      middle_name TEXT,
      last_name TEXT NOT NULL,
      preferred_name TEXT,
      household_id TEXT,
      mailing_address TEXT,
      email TEXT,
      phone TEXT,
      statement_delivery TEXT NOT NULL DEFAULT 'mail',
      active INTEGER NOT NULL DEFAULT 1,
      statement_eligible INTEGER NOT NULL DEFAULT 1,
      envelope_number TEXT UNIQUE,
      envelope_code TEXT UNIQUE,
      envelope_code_status TEXT NOT NULL DEFAULT 'inactive',
      envelope_code_issued_at TEXT,
      envelope_code_updated_at TEXT,
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL
    , directory_contact_id TEXT REFERENCES directory_contacts(id) ON DELETE SET NULL, account_number TEXT, donor_kind TEXT NOT NULL DEFAULT 'member', merged_into_donor_id TEXT REFERENCES finance_donors(id) ON DELETE SET NULL);
CREATE TABLE finance_donor_envelope_codes (
      id TEXT PRIMARY KEY,
      donor_id TEXT NOT NULL REFERENCES finance_donors(id) ON DELETE CASCADE,
      envelope_code TEXT NOT NULL UNIQUE,
      envelope_number_snapshot TEXT,
      status TEXT NOT NULL,
      issued_at TEXT NOT NULL,
      updated_at TEXT NOT NULL,
      replaced_by_code TEXT,
      note TEXT
    );
CREATE TABLE finance_collection_batches (
      id TEXT PRIMARY KEY,
      service_date TEXT NOT NULL,
      service_name TEXT,
      status TEXT NOT NULL DEFAULT 'draft',
      declared_physical_cash_cents INTEGER NOT NULL DEFAULT 0,
      declared_check_cents INTEGER NOT NULL DEFAULT 0,
      calculated_envelope_total_cents INTEGER NOT NULL DEFAULT 0,
      calculated_loose_cash_total_cents INTEGER NOT NULL DEFAULT 0,
      calculated_batch_total_cents INTEGER NOT NULL DEFAULT 0,
      discrepancy_cents INTEGER NOT NULL DEFAULT 0,
      discrepancy_explanation TEXT,
      count_sheet_attachment_ref TEXT,
      created_by TEXT NOT NULL,
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL,
      finalized_at TEXT,
      voided_at TEXT,
      voided_by TEXT,
      void_reason TEXT,
      deposit_date TEXT,
      deposit_reference TEXT,
      deposited_amount_cents INTEGER,
      deposit_confirmed_at TEXT,
      deposit_verified_by TEXT,
      deposit_internal_control_exception TEXT,
      approval_version INTEGER NOT NULL DEFAULT 0
    );
CREATE TABLE finance_collection_counters (
      id TEXT PRIMARY KEY,
      batch_id TEXT NOT NULL REFERENCES finance_collection_batches(id) ON DELETE CASCADE,
      counter_email TEXT NOT NULL,
      assigned_by TEXT NOT NULL,
      assigned_at TEXT NOT NULL,
      UNIQUE(batch_id, counter_email)
    );
CREATE TABLE finance_collection_counter_approvals (
      id TEXT PRIMARY KEY,
      batch_id TEXT NOT NULL REFERENCES finance_collection_batches(id) ON DELETE CASCADE,
      counter_email TEXT NOT NULL,
      approved_by TEXT NOT NULL,
      approved_at TEXT NOT NULL,
      batch_version INTEGER NOT NULL,
      UNIQUE(batch_id, counter_email, batch_version)
    );
CREATE TABLE finance_collection_envelopes (
      id TEXT PRIMARY KEY,
      batch_id TEXT NOT NULL REFERENCES finance_collection_batches(id) ON DELETE CASCADE,
      donor_id TEXT NOT NULL REFERENCES finance_donors(id),
      envelope_code_snapshot TEXT,
      envelope_number_snapshot TEXT,
      payment_method TEXT NOT NULL,
      check_number TEXT,
      envelope_total_cents INTEGER NOT NULL,
      entry_status TEXT NOT NULL DEFAULT 'active',
      created_by TEXT NOT NULL,
      updated_by TEXT NOT NULL,
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL
    , transaction_kind TEXT NOT NULL DEFAULT 'registered_envelope');
CREATE TABLE finance_collection_allocations (
      id TEXT PRIMARY KEY,
      envelope_entry_id TEXT NOT NULL REFERENCES finance_collection_envelopes(id) ON DELETE CASCADE,
      fund_id TEXT,
      fund_code TEXT,
      amount_cents INTEGER NOT NULL,
      note TEXT,
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL
    );
CREATE TABLE finance_collection_loose_giving (
      id TEXT PRIMARY KEY,
      batch_id TEXT NOT NULL REFERENCES finance_collection_batches(id) ON DELETE CASCADE,
      fund_id TEXT,
      fund_code TEXT,
      payment_method TEXT NOT NULL,
      amount_cents INTEGER NOT NULL,
      note TEXT,
      created_by TEXT NOT NULL,
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL
    );
CREATE TABLE finance_collection_audit_events (
      id TEXT PRIMARY KEY,
      batch_id TEXT,
      donor_id TEXT,
      envelope_entry_id TEXT,
      event_type TEXT NOT NULL,
      event_action TEXT NOT NULL,
      actor_email TEXT NOT NULL,
      reason TEXT,
      metadata_json TEXT,
      created_at TEXT NOT NULL
    );
CREATE TABLE finance_scan_codes (
      id TEXT PRIMARY KEY,
      code_value TEXT NOT NULL,
      code_family TEXT NOT NULL,
      donor_id TEXT REFERENCES finance_donors(id) ON DELETE SET NULL,
      status TEXT NOT NULL DEFAULT 'active',
      issued_at TEXT NOT NULL,
      updated_at TEXT NOT NULL,
      replaced_by_code_value TEXT,
      note TEXT,
      created_by TEXT
    );
CREATE TABLE directory_contacts (
  id TEXT PRIMARY KEY,
  first_name TEXT NOT NULL,
  middle_name TEXT,
  last_name TEXT NOT NULL,
  preferred_name TEXT,
  suffix TEXT,
  contact_type TEXT NOT NULL DEFAULT 'member',
  membership_status TEXT,
  status TEXT NOT NULL DEFAULT 'active',
  primary_email TEXT,
  secondary_email TEXT,
  mobile_phone TEXT,
  home_phone TEXT,
  preferred_contact_method TEXT,
  address_line_1 TEXT,
  address_line_2 TEXT,
  city TEXT,
  state TEXT,
  postal_code TEXT,
  birth_month INTEGER,
  birth_day INTEGER,
  anniversary_month INTEGER,
  anniversary_day INTEGER,
  member_since TEXT,
  notes TEXT,
  created_by TEXT,
  updated_by TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  archived_at TEXT,
  account_number TEXT,
  normalized_primary_phone TEXT,
  normalized_home_phone TEXT
);
CREATE TABLE newsletter_subscribers (
  id TEXT PRIMARY KEY,
  contact_id TEXT REFERENCES directory_contacts(id) ON DELETE SET NULL,
  email TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'pending',
  consent_source TEXT,
  consent_date TEXT,
  confirmed_at TEXT,
  unsubscribed_at TEXT,
  suppression_reason TEXT,
  last_emailed_at TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE TABLE directory_groups (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  category TEXT NOT NULL DEFAULT 'ministry',
  description TEXT,
  status TEXT NOT NULL DEFAULT 'active',
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE TABLE directory_group_members (
  id TEXT PRIMARY KEY,
  group_id TEXT NOT NULL REFERENCES directory_groups(id) ON DELETE CASCADE,
  contact_id TEXT NOT NULL REFERENCES directory_contacts(id) ON DELETE CASCADE,
  role TEXT,
  joined_at TEXT NOT NULL,
  ended_at TEXT,
  notes TEXT
);
CREATE TABLE newsletter_lists (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  description TEXT,
  status TEXT NOT NULL DEFAULT 'active',
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE TABLE newsletter_list_members (
  id TEXT PRIMARY KEY,
  list_id TEXT NOT NULL REFERENCES newsletter_lists(id) ON DELETE CASCADE,
  subscriber_id TEXT NOT NULL REFERENCES newsletter_subscribers(id) ON DELETE CASCADE,
  added_at TEXT NOT NULL,
  removed_at TEXT
);
CREATE TABLE directory_activity_log (
  id TEXT PRIMARY KEY,
  actor_email TEXT,
  event_type TEXT NOT NULL,
  entity_type TEXT NOT NULL,
  entity_id TEXT,
  summary TEXT,
  metadata_json TEXT,
  created_at TEXT NOT NULL
);
CREATE TABLE admin_users (
  id TEXT PRIMARY KEY,
  email TEXT NOT NULL COLLATE NOCASE UNIQUE,
  full_name TEXT NOT NULL DEFAULT '',
  role TEXT NOT NULL DEFAULT 'website_editor'
    CHECK (role IN ('administrator', 'website_editor', 'finance_entry', 'treasurer', 'auditor')),
  status TEXT NOT NULL DEFAULT 'pending'
    CHECK (status IN ('pending', 'active', 'suspended', 'revoked')),
  invited_by TEXT,
  invited_at TEXT NOT NULL,
  activated_at TEXT,
  last_login_at TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE TABLE admin_audit_log (
  id TEXT PRIMARY KEY,
  actor_user_id TEXT,
  actor_email TEXT NOT NULL COLLATE NOCASE,
  action TEXT NOT NULL,
  target_user_id TEXT,
  target_email TEXT COLLATE NOCASE,
  previous_value_json TEXT,
  new_value_json TEXT,
  created_at TEXT NOT NULL,
  FOREIGN KEY (actor_user_id) REFERENCES admin_users(id) ON DELETE SET NULL,
  FOREIGN KEY (target_user_id) REFERENCES admin_users(id) ON DELETE SET NULL
);
CREATE TABLE newsletter_suppressions (email TEXT PRIMARY KEY COLLATE NOCASE, reason TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE newsletter_deliveries (
 campaign_id TEXT NOT NULL, email TEXT NOT NULL COLLATE NOCASE, status TEXT NOT NULL DEFAULT 'pending',
 provider_id TEXT, attempts INTEGER NOT NULL DEFAULT 0, error TEXT NOT NULL DEFAULT '', updated_at TEXT NOT NULL,
 PRIMARY KEY(campaign_id,email)
);
CREATE TABLE contact_messages (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  email TEXT NOT NULL,
  phone TEXT,
  address TEXT,
  message TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'received', 
  email_error TEXT,
  created_at TEXT NOT NULL
, subject TEXT NOT NULL DEFAULT 'General Website Inquiry', read_at TEXT, archived_at TEXT, auto_reply_status TEXT NOT NULL DEFAULT 'pending', auto_reply_at TEXT, auto_reply_error TEXT, first_name TEXT, last_name TEXT, address_line1 TEXT, address_line2 TEXT, city TEXT, state TEXT, postal_code TEXT);
CREATE TABLE facility_rental_requests (
  id TEXT PRIMARY KEY,
  audience TEXT NOT NULL DEFAULT 'member', 
  person_responsible TEXT NOT NULL,
  phone TEXT NOT NULL,
  purpose TEXT NOT NULL,
  date_of_use TEXT NOT NULL,
  time_from TEXT NOT NULL,
  time_to TEXT NOT NULL,
  contact_email TEXT,
  form_json TEXT NOT NULL DEFAULT '{}', 
  status TEXT NOT NULL DEFAULT 'received', 
  email_error TEXT,
  created_at TEXT NOT NULL
, read_at TEXT, archived_at TEXT, auto_reply_status TEXT NOT NULL DEFAULT 'pending', auto_reply_at TEXT, auto_reply_error TEXT, first_name TEXT, last_name TEXT, address TEXT, address_line1 TEXT, address_line2 TEXT, city TEXT, state TEXT, postal_code TEXT);
CREATE TABLE form_rate_limits (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  rate_key TEXT NOT NULL,
  created_at TEXT NOT NULL
);
CREATE TABLE email_delivery_jobs (
 id TEXT PRIMARY KEY, submission_id TEXT NOT NULL, submission_type TEXT NOT NULL,
 kind TEXT NOT NULL, payload_json TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending',
 attempts INTEGER NOT NULL DEFAULT 0, next_attempt_at TEXT NOT NULL, error TEXT NOT NULL DEFAULT '',
 created_at TEXT NOT NULL, updated_at TEXT NOT NULL
);
CREATE TABLE mailbox_state (
  item_key TEXT PRIMARY KEY,
  folder TEXT NOT NULL DEFAULT 'inbox' CHECK(folder IN ('inbox','archive','deleted')),
  is_read INTEGER NOT NULL DEFAULT 0 CHECK(is_read IN (0,1)),
  starred INTEGER NOT NULL DEFAULT 0 CHECK(starred IN (0,1)),
  updated_at TEXT NOT NULL,
  updated_by TEXT NOT NULL
);
CREATE TABLE mailbox_drafts (
  actor TEXT NOT NULL, draft_key TEXT NOT NULL,
  recipient TEXT NOT NULL DEFAULT '', subject TEXT NOT NULL DEFAULT '', body TEXT NOT NULL DEFAULT '',
  item_key TEXT NOT NULL DEFAULT '', idempotency_key TEXT NOT NULL,
  updated_at TEXT NOT NULL, PRIMARY KEY(actor,draft_key)
);
CREATE TABLE mailbox_outbound (
  id TEXT PRIMARY KEY, item_key TEXT NOT NULL DEFAULT '', actor TEXT NOT NULL,
  recipient TEXT NOT NULL, subject TEXT NOT NULL, body TEXT NOT NULL,
  idempotency_key TEXT NOT NULL UNIQUE,
  status TEXT NOT NULL DEFAULT 'queued' CHECK(status IN ('queued','sending','accepted','failed','uncertain')),
  provider_id TEXT, error TEXT, attempts INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL, updated_at TEXT NOT NULL, accepted_at TEXT
);
CREATE TABLE rental_workflow (
  rental_id TEXT PRIMARY KEY REFERENCES facility_rental_requests(id) ON DELETE CASCADE,
  status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','declined')),
  version INTEGER NOT NULL DEFAULT 0, updated_by TEXT NOT NULL, updated_at TEXT NOT NULL
);
CREATE TABLE workspace_audit (
  id TEXT PRIMARY KEY, actor TEXT NOT NULL, item_key TEXT NOT NULL,
  action TEXT NOT NULL, value_json TEXT NOT NULL, created_at TEXT NOT NULL
);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_gallery_album ON gallery_items(album);
CREATE INDEX idx_gallery_created_at ON gallery_items(created_at);
CREATE INDEX idx_giving_paid_at ON giving_donations(paid_at);
CREATE INDEX idx_giving_fund ON giving_donations(fund_code);
CREATE INDEX idx_giving_email ON giving_donations(donor_email);
CREATE INDEX idx_subscription_payments_paid_at ON giving_subscription_payments(paid_at);
CREATE INDEX idx_subscription_payments_subscription ON giving_subscription_payments(stripe_subscription_id);
CREATE INDEX idx_subscription_payments_fund ON giving_subscription_payments(fund_code);
CREATE INDEX idx_subscriptions_status ON giving_subscriptions(status);
CREATE INDEX idx_subscriptions_email ON giving_subscriptions(donor_email);
CREATE INDEX idx_gallery_is_hidden_created_at ON gallery_items(is_hidden, created_at DESC);
CREATE UNIQUE INDEX idx_finance_envelope_unique_batch_code ON finance_collection_envelopes(batch_id, envelope_code_snapshot);
CREATE INDEX idx_finance_donors_name ON finance_donors(last_name, first_name);
CREATE INDEX idx_finance_donors_envelope_number ON finance_donors(envelope_number);
CREATE INDEX idx_finance_donor_codes_code ON finance_donor_envelope_codes(envelope_code);
CREATE INDEX idx_finance_batch_service_date ON finance_collection_batches(service_date);
CREATE INDEX idx_finance_batch_status ON finance_collection_batches(status);
CREATE INDEX idx_finance_envelope_batch ON finance_collection_envelopes(batch_id, created_at);
CREATE INDEX idx_finance_envelope_donor ON finance_collection_envelopes(donor_id, created_at);
CREATE INDEX idx_finance_alloc_fund ON finance_collection_allocations(fund_id, fund_code);
CREATE INDEX idx_finance_loose_batch ON finance_collection_loose_giving(batch_id, created_at);
CREATE INDEX idx_finance_audit_batch_time ON finance_collection_audit_events(batch_id, created_at);
CREATE UNIQUE INDEX idx_finance_scan_codes_value ON finance_scan_codes(code_value);
CREATE INDEX idx_finance_scan_codes_family_status ON finance_scan_codes(code_family, status);
CREATE UNIQUE INDEX idx_newsletter_subscribers_email
  ON newsletter_subscribers(email);
CREATE INDEX idx_directory_contacts_status_archived
  ON directory_contacts(status, archived_at);
CREATE INDEX idx_directory_contacts_name
  ON directory_contacts(last_name, first_name);
CREATE INDEX idx_directory_contacts_email
  ON directory_contacts(primary_email);
CREATE INDEX idx_directory_contacts_mobile_norm
  ON directory_contacts(normalized_primary_phone);
CREATE INDEX idx_directory_contacts_home_norm
  ON directory_contacts(normalized_home_phone);
CREATE UNIQUE INDEX idx_directory_contacts_account_number_unique
  ON directory_contacts(account_number)
  WHERE account_number IS NOT NULL AND trim(account_number) <> '';
CREATE INDEX idx_directory_group_members_group
  ON directory_group_members(group_id, ended_at);
CREATE INDEX idx_directory_group_members_contact
  ON directory_group_members(contact_id, ended_at);
CREATE INDEX idx_newsletter_subscribers_status
  ON newsletter_subscribers(status);
CREATE INDEX idx_newsletter_subscribers_contact
  ON newsletter_subscribers(contact_id);
CREATE INDEX idx_newsletter_lists_status
  ON newsletter_lists(status);
CREATE INDEX idx_newsletter_list_members_list
  ON newsletter_list_members(list_id, removed_at);
CREATE INDEX idx_newsletter_list_members_subscriber
  ON newsletter_list_members(subscriber_id, removed_at);
CREATE INDEX idx_directory_activity_entity
  ON directory_activity_log(entity_type, entity_id, created_at);
CREATE INDEX idx_directory_activity_actor
  ON directory_activity_log(actor_email, created_at);
CREATE UNIQUE INDEX idx_finance_donors_directory_contact_unique
  ON finance_donors(directory_contact_id)
  WHERE directory_contact_id IS NOT NULL AND trim(directory_contact_id) <> '';
CREATE UNIQUE INDEX idx_finance_donors_account_number_unique
  ON finance_donors(account_number)
  WHERE account_number IS NOT NULL AND trim(account_number) <> '';
CREATE INDEX idx_finance_donors_account_number
  ON finance_donors(account_number);
CREATE INDEX idx_finance_donors_kind
  ON finance_donors(donor_kind, active);
CREATE INDEX idx_finance_donors_merged_into
  ON finance_donors(merged_into_donor_id);
CREATE INDEX idx_admin_users_status_role
  ON admin_users(status, role);
CREATE INDEX idx_admin_users_email_normalized
  ON admin_users(lower(email));
CREATE INDEX idx_admin_users_role
  ON admin_users(role);
CREATE INDEX idx_admin_users_status
  ON admin_users(status);
CREATE INDEX idx_admin_users_last_login
  ON admin_users(last_login_at);
CREATE INDEX idx_admin_audit_created_at
  ON admin_audit_log(created_at DESC);
CREATE INDEX idx_admin_audit_actor
  ON admin_audit_log(actor_email, created_at DESC);
CREATE INDEX idx_admin_audit_target
  ON admin_audit_log(target_user_id, created_at DESC);
CREATE INDEX idx_admin_audit_target_email
  ON admin_audit_log(target_email, created_at DESC);
CREATE INDEX idx_contact_messages_created_at ON contact_messages(created_at);
CREATE INDEX idx_facility_rental_requests_created_at ON facility_rental_requests(created_at);
CREATE INDEX idx_facility_rental_requests_date_of_use ON facility_rental_requests(date_of_use);
CREATE INDEX idx_form_rate_limits_key_created ON form_rate_limits(rate_key, created_at);
CREATE INDEX idx_contact_messages_status ON contact_messages(status, archived_at, created_at);
CREATE INDEX idx_facility_rental_status ON facility_rental_requests(status, archived_at, created_at);
CREATE INDEX idx_delivery_jobs_due ON email_delivery_jobs(status,next_attempt_at);
CREATE INDEX idx_mailbox_state_folder ON mailbox_state(folder,is_read,starred);
CREATE INDEX idx_mailbox_outbound_thread ON mailbox_outbound(item_key,created_at);
CREATE INDEX idx_mailbox_outbound_actor ON mailbox_outbound(actor,created_at);
CREATE INDEX idx_rental_workflow_status ON rental_workflow(status);
CREATE INDEX idx_workspace_audit_item ON workspace_audit(item_key,created_at);
CREATE INDEX idx_events_event_date ON events(event_date, event_time);
CREATE INDEX idx_announcements_created_at ON announcements(created_at);
CREATE INDEX idx_newsletter_records_status_schedule ON newsletter_records(status, schedule_at);
CREATE INDEX idx_finance_entries_date ON finance_entries(entry_date DESC, created_at DESC);
CREATE INDEX idx_finance_entries_type_date ON finance_entries(type, entry_date DESC);
